1. In apps/web/src/components/forget-refusal.tsx, move the rewrite into a pure exported function and have the effect call it:

```ts
export function forgetRefusalUrl(href: string, extra: readonly string[] = []): string | null {
  const url = new URL(href);
  const keys = [...REFUSAL_QUERY_KEYS, ...extra].filter((key) => url.searchParams.has(key));
  if (keys.length === 0) return null;
  for (const key of keys) url.searchParams.delete(key);
  return `${url.pathname}${url.search}${url.hash}`;
}
```

ForgetRefusal takes `{ forget?: readonly string[] }`, and its effect calls `history.replaceState` only when the function returns a string.

