verify-ux-UX-DLR-15.fix:
Use the setCustomValidity version of the fix. Do not disable optgroups or reset the contract.

(1) Add apps/web/src/components/coverage/letter-contract-check.tsx, following the pattern of forget-refusal.tsx:

'use client';
import { useEffect } from 'react';
/** Stops a contract of another payer before the letter is sent. The route's check stays the rule (docs/adr/0079). */
export function LetterContractCheck({ message }: { readonly message: string }) {
  useEffect(() => {
    const payer = document.getElementById('letter-payer');
    const contract = document.getElementById('letter-contract');
    if (!(payer instanceof HTMLSelectElement) || !(contract instanceof HTMLSelectElement)) return;
    const check = () => {
      const owner = contract.selectedOptions[0]?.dataset.payer;
      contract.setCustomValidity(owner !== undefined && owner !== payer.value ? message : '');
    };
    check();
    payer.addEventListener('change', check);
    contract.addEventListener('change', check);
    return () => {
      payer.removeEventListener('change', check);
      contract.removeEventListener('change', check);
    };
  }, [message]);
  return null;
}

